<body data-donation-page="dashboard">
<div class="app">
<aside class="side" id="sidebar">
 <div class="brand"><div class="brand-logo"><i data-lucide="heart-pulse" width="24" height="24"></i></div><div><strong>মান্দা রক্ত দান</strong><small>DONATION MANAGEMENT</small></div></div>
 <div class="section-label">মেইন মেনু</div>
 <nav class="nav" id="nav">
  <button class="active" data-page="dashboard"><i data-lucide="layout-dashboard"></i> ড্যাশবোর্ড</button>
  <button data-page="donors"><i data-lucide="users-round"></i> রক্তদাতার তালিকা</button>
  <button data-page="requests"><i data-lucide="clipboard-list"></i> রক্তের অনুরোধ <span class="count" id="openRequestCount">০</span></button>
  <button data-page="groups"><i data-lucide="droplets"></i> ব্লাড গ্রুপ</button>
  <button data-page="areas"><i data-lucide="map-pin"></i> এলাকা ভিত্তিক তথ্য</button>
 </nav>
 <div class="section-label" style="margin-top:26px">ম্যানেজমেন্ট</div>
 <nav class="nav"><button data-page="reports"><i data-lucide="chart-column-increasing"></i> রিপোর্ট ও পরিসংখ্যান</button><button data-page="settings"><i data-lucide="settings-2"></i> সেটিংস</button></nav>
 <div class="sidebar-bottom"><div class="help"><strong>জীবন বাঁচাতে পাশে থাকুন</strong><p>আপনার একটি ছোট উদ্যোগ বদলে দিতে পারে কারও জীবন।</p><button onclick="openModal()">+ নতুন রক্তদাতা</button></div><div class="adminmini"><div class="avatar">AD</div><div><strong>অ্যাডমিন প্যানেল</strong><small>সুপার অ্যাডমিন</small></div><i data-lucide="chevrons-up-down" style="margin-left:auto;color:#99a3ad;width:15px"></i></div></div>
</aside>
<main class="main"><header class="topbar"><div style="display:flex;align-items:center;gap:14px"><button class="iconbtn mobile-menu" onclick="document.getElementById('sidebar').classList.toggle('open')" style="border:0;background:none"><i data-lucide="menu"></i></button><div class="breadcrumbs">পেজ / <span id="crumb">ড্যাশবোর্ড</span></div></div><div class="top-actions"><span style="font-size:12px;color:#919ca7" id="today"></span><button class="iconbtn" onclick="showToast('এখন কোনো নতুন নোটিফিকেশন নেই')"><i data-lucide="bell" width="20"></i><span class="dot"></span></button><div class="userline"><div class="avatar">AD</div><div><b>অ্যাডমিন</b><small>অ্যাডমিনিস্ট্রেটর</small></div></div></div></header>
<div class="content">
 <div class="heading"><div><h1 id="pageTitle">ড্যাশবোর্ড ওভারভিউ <span style="font-size:24px">👋</span></h1><p id="pageSubtitle">মান্দা রক্ত দান কর্মসূচির সার্বিক কার্যক্রম এক নজরে দেখুন</p></div><div class="heading-actions"><button class="btn" onclick="exportCSV()"><i data-lucide="download"></i> এক্সপোর্ট</button><button class="btn primary" onclick="openModal()"><i data-lucide="plus"></i> নতুন রক্তদাতা</button></div></div>
 <section class="cards" id="stats"></section>
 <div id="dashboardExtra" class="navview active"><section class="split"><div class="panel panel-pad"><div class="panelhead"><div><h2>রক্তদানের কার্যক্রম</h2><p>গত কয়েক মাসের রক্তদানের পরিসংখ্যান</p></div><select class="smallselect" id="chartPeriod" onchange="drawChart()"><option value="6">গত ৬ মাস</option><option value="3">গত ৩ মাস</option></select></div><div class="chart-area" id="chart"></div><div class="chart-legend"><span><i class="legenddot"></i> সম্পন্ন রক্তদান</span><span>মাসভিত্তিক তথ্য</span></div></div><div class="panel panel-pad"><div class="panelhead"><div><h2>ব্লাড গ্রুপ অনুযায়ী দাতা</h2><p>নিবন্ধিত রক্তদাতাদের গ্রুপভিত্তিক তথ্য</p></div><i data-lucide="ellipsis" style="color:#9ca5af"></i></div><div class="bloodlist" id="bloodBars"></div></div></section></div>
 <section class="panel directory" id="directory"><div class="dirheader"><div><h2>রক্তদাতাদের তালিকা</h2><p>উপলব্ধ মানে যোগাযোগযোগ্য; মেডিক্যালি রক্তদানে যোগ্যতার নিশ্চয়তা নয়।</p></div><button class="btn" onclick="selectPage('donors')">সব দেখুন <i data-lucide="arrow-up-right"></i></button></div><div class="dirtools"><label class="search"><i data-lucide="search"></i><input id="search" placeholder="নাম, এলাকা বা মোবাইল দিয়ে খুঁজুন..." oninput="renderTable()"></label><select class="filter" id="groupFilter" onchange="renderTable()"><option value="">সকল ব্লাড গ্রুপ</option><option>A+</option><option>A-</option><option>B+</option><option>B-</option><option>AB+</option><option>AB-</option><option>O+</option><option>O-</option></select><select class="filter" id="areaFilter" onchange="renderTable()"><option value="">সকল এলাকা</option></select><select class="filter" id="statusFilter" onchange="renderTable()"><option value="">সকল স্ট্যাটাস</option><option value="available">উপলব্ধ</option><option value="busy">অনুপলব্ধ</option></select></div><div class="tablewrap"><table><thead><tr><th>রক্তদাতার নাম</th><th>ব্লাড গ্রুপ</th><th>ঠিকানা / এলাকা</th><th>সর্বশেষ রক্তদান</th><th>অবস্থা</th><th>যোগাযোগ</th></tr></thead><tbody id="donorRows"></tbody></table></div><div class="tablefooter"><span id="tableCount"></span><div class="pagination" id="pagination"></div></div></section>
 <section class="navview" id="requestsView"><div class="panel panel-pad"><div class="panelhead"><div><h2>জরুরি রক্তের অনুরোধ</h2><p>রক্তের অনুরোধ, ম্যাচিং ও রক্তদান পরিচালনা করুন</p></div><button class="btn primary" onclick="openRequestForm()">+ অনুরোধ যোগ করুন</button></div><div class="request-list" id="requestList"></div></div></section>
 <section class="navview" id="settingsView"><div class="panel panel-pad"><h2>সিস্টেম সেটিংস</h2><div id="settingsList"></div></div></section>
 </div></main></div>
<div class="overlay" id="modalOverlay" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-header"><div><h2>নতুন রক্তদাতা যুক্ত করুন</h2><p style="margin:3px 0;color:#98a3ac">সম্মতি নিয়ে তথ্য যুক্ত করুন। যাচাইকৃত রক্তদান থেকেই ইতিহাস আপডেট হবে।</p></div><button class="close" onclick="closeModal()">×</button></div><form id="donorForm"><div class="formgrid"><div class="field"><label>পুরো নাম *</label><input name="name" required placeholder="রক্তদাতার নাম"></div><div class="field"><label>ব্লাড গ্রুপ *</label><select name="group" required><option value="">নির্বাচন করুন</option><option>A+</option><option>A-</option><option>B+</option><option>B-</option><option>AB+</option><option>AB-</option><option>O+</option><option>O-</option></select></div><div class="field"><label>মোবাইল নম্বর *</label><input name="phone" required pattern="[0-9+\- ]{10,16}" placeholder="01XXXXXXXXX"></div><div class="field"><label>এলাকা *</label><input name="area" required placeholder="যেমন: মান্দা সদর"></div><div class="field full"><label>বিস্তারিত ঠিকানা</label><input name="address" placeholder="গ্রাম, ইউনিয়ন, উপজেলা"></div><div class="field"><label>বর্তমান অবস্থা</label><select name="status"><option value="available">উপলব্ধ</option><option value="busy">অনুপলব্ধ</option></select></div></div><label style="display:flex;gap:8px;align-items:flex-start;color:#6e7b86;font-size:12px;margin-top:18px"><input type="checkbox" required style="margin-top:4px"> রক্তদাতার তথ্য সংরক্ষণ ও যোগাযোগের অনুরোধ গ্রহণের সম্মতি নেওয়া হয়েছে।</label><div class="modal-actions"><button type="button" class="btn" onclick="closeModal()">বাতিল</button><button type="submit" class="btn primary">রক্তদাতা সংরক্ষণ</button></div></form></div></div>
<div class="toast" id="toast"></div>
